  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <div class="page-shell" id="app"></div>

    <script>
      const app = document.getElementById("app");

      const Field = ({ id, label, type = "text", autocomplete, required = false, help = "", placeholder = "" }) => `
        <div class="form-field">
          <label for="${id}">
            ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
            ${required ? "required" : ""}
            ${placeholder ? `placeholder="${placeholder}"` : ""}
            aria-describedby="${[help ? `${id}-help` : null, `${id}-error`].filter(Boolean).join(" ")}"
          />
          ${help ? `<p class="field-help" id="${id}-help">${help}</p>` : ""}
          <p class="field-error" id="${id}-error" hidden></p>
        </div>
      `;

      const App = () => `
        <header class="hero">
          <p class="eyebrow">Support</p>
          <h1 id="page-title">Contact our team</h1>
          <p class="intro">Tell us what you need and we'll route your request to the right person.</p>
        </header>

        <main id="maincontent" tabindex="-1" class="layout" aria-labelledby="page-title">
          <section class="panel form-panel" aria-labelledby="contact-form-title">
            <h2 class="section-title" id="contact-form-title">Send a message</h2>
            <p class="section-copy">Fields marked with an asterisk are required.</p>

            <form id="support-form" novalidate>
              ${Field({
                id: "full-name",
                label: "Full name",
                autocomplete: "name",
                required: true,
                placeholder: "Jane Doe"
              })}

              ${Field({
                id: "email-address",
                label: "Email address",
                type: "email",
                autocomplete: "email",
                required: true,
                placeholder: "jane@example.com"
              })}

              ${Field({
                id: "phone-number",
                label: "Phone number",
                type: "tel",
                autocomplete: "tel",
                help: "Format: +1 555 123 4567 or (555) 123-4567."
              })}

              <div class="actions">
                <button type="submit">Send message</button>
                <p class="fine-print">We use this form only for support follow-up.</p>
              </div>

              <p id="form-status" class="status" aria-live="polite"></p>
            </form>
          </section>

          <aside class="panel support-panel" aria-labelledby="support-guidance-title">
            <h2 class="section-title" id="support-guidance-title">What to include</h2>
            <p class="section-copy">A few details help us respond faster.</p>
            <ul class="sidebar-list">
              <li class="sidebar-item">
                <strong>Account or product context</strong>
                <span>Tell us where you ran into the issue.</span>
              </li>
              <li class="sidebar-item">
                <strong>Best way to reach you</strong>
                <span>Phone is optional, but useful for urgent cases.</span>
              </li>
              <li class="sidebar-item">
                <strong>Anything time-sensitive</strong>
                <span>Include deadlines or recent changes if they matter.</span>
              </li>
            </ul>
          </aside>
        </main>

        <footer>
          <p>Support is available Monday through Friday.</p>
        </footer>
      `;

      app.innerHTML = App();

      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");
      const fields = [
        {
          element: document.getElementById("full-name"),
          label: "Full name",
          required: true,
          validate(value) {
            return value.trim() ? "" : "Full name is required.";
          }
        },
        {
          element: document.getElementById("email-address"),
          label: "Email address",
          required: true,
          validate(value) {
            if (!value.trim()) return "Email address is required.";
            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
              return "Enter a valid email address, like name@example.com.";
            }
            return "";
          }
        },
        {
          element: document.getElementById("phone-number"),
          label: "Phone number",
          required: false,
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) return "";
            if (!/^[+()\-.\s\d]{7,}$/.test(trimmed)) {
              return "Use a phone number in a format like +1 555 123 4567 or (555) 123-4567.";
            }
            return "";
          }
        }
      ];

      function setFieldState(field, message) {
        const errorEl = document.getElementById(`${field.element.id}-error`);
        if (message) {
          field.element.setAttribute("aria-invalid", "true");
          errorEl.textContent = `Error: ${message}`;
          errorEl.hidden = false;
        } else {
          field.element.removeAttribute("aria-invalid");
          errorEl.textContent = "";
          errorEl.hidden = true;
        }
      }

      function validateForm() {
        let firstInvalid = null;
        let hasErrors = false;

        fields.forEach((field) => {
          const message = field.validate(field.element.value);
          setFieldState(field, message);
          if (message && !firstInvalid) firstInvalid = field.element;
          if (message) hasErrors = true;
        });

        return { hasErrors, firstInvalid };
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const { hasErrors, firstInvalid } = validateForm();

        if (hasErrors) {
          status.textContent = "Please fix the highlighted fields and try again.";
          status.dataset.state = "error";
          firstInvalid.focus();
          return;
        }

        status.textContent = "Thanks — your message is ready to send.";
        status.dataset.state = "success";
        form.reset();
        fields.forEach((field) => setFieldState(field, ""));
        fields[0].element.focus();
      });

      fields.forEach((field) => {
        field.element.addEventListener("input", () => {
          if (field.element.hasAttribute("aria-invalid")) {
            setFieldState(field, field.validate(field.element.value));
          }
        });
      });
    </script>
  </body>
</html>
